function getDonQuixoteWord(count: number): string {
  if (count === 1) {
    return "Дон-Кихот";
  }

  if (count >= 2 && count <= 4) {
    return "Дон-Кихота";
  }

  return "Дон-Кихотов";
}

function shuffleQuestions(
  questions: SurveyQuestion[],
): SurveyQuestion[] {
  const result = [...questions];

  // Алгоритм Фишера — Йетса.
  for (let index = result.length - 1; index > 0; index -= 1) {
    const randomIndex = Math.floor(Math.random() * (index + 1));

    [result[index], result[randomIndex]] = [
      result[randomIndex],
      result[index],
    ];
  }

  return result;
}

export const MindTest: FC = () => {
  const [surveyNumber, setSurveyNumber] = useState(1);
  const [answers, setAnswers] = useState<Answers>({});
  const [isChecked, setIsChecked] = useState(false);

  const questions = useMemo(
    () => shuffleQuestions(SURVEY_QUESTIONS),
    [surveyNumber],
  );

  const answeredCount = Object.keys(answers).length;
  const allQuestionsAnswered =
    answeredCount === questions.length;

  const result = useMemo(() => {
    let correctOpinions = 0;
    let correctFacts = 0;

    questions.forEach((question) => {
      // Два пограничных утверждения в результат не входят.
      if (question.type === null) {
        return;
      }

      const answer = answers[question.id];

      if (answer !== question.type) {
        return;
      }

      if (question.type === 0) {
        correctOpinions += 1;
      } else {
        correctFacts += 1;
      }
    });

    const correctAnswers = correctOpinions + correctFacts;
    const incorrectAnswers = SCORED_QUESTIONS_COUNT - correctAnswers;

    return {
      correctOpinions,
      correctFacts,
      incorrectAnswers,
      stupidityScore: incorrectAnswers,
    };
  }, [answers, questions]);

  const handleAnswer = (
    questionId: number,
    answer: AnswerType,
  ) => {
    if (isChecked) {
      return;
    }

    setAnswers((currentAnswers) => ({
      ...currentAnswers,
      [questionId]: answer,
    }));
  };

  const handleCheck = () => {
    if (!allQuestionsAnswered) {
      return;
    }

    setIsChecked(true);
  };

  const handleRestart = () => {
    if (document.activeElement instanceof HTMLElement) {
      document.activeElement.blur();
    }    
    setAnswers({});
    setIsChecked(false);
    setSurveyNumber((currentNumber) => currentNumber + 1);
  };

  return (
    <main style={styles.page}>
      <section style={styles.container}>
        <header style={styles.header}>
          <p style={styles.eyebrow}>
            Опрос по материалам Pew Research Center
          </p>

          <h1 style={styles.title}>
            Факт или мнение?
          </h1>

          <p style={styles.description}>
            Для каждого утверждения определите, является ли оно
            фактом, который можно объективно доказать или
            опровергнуть, либо мнением, выражающим оценку или
            убеждение.
          </p>

          <div style={styles.progress}>
            Отвечено: {answeredCount} из {questions.length}
          </div>
        </header>

        <div 
          style={styles.questions}
           key={surveyNumber}
        >
          {questions.map((question, index) => {
            const selectedAnswer = answers[question.id];

            return (
              <article
                key={question.id}
                style={styles.questionCard}
              >
                <div style={styles.questionNumber}>
                  Утверждение {index + 1}
                </div>

                <p style={styles.questionText}>
                  {question.name}
                </p>

                <div
                  style={styles.answerButtons}
                  role="radiogroup"
                  aria-label={`Ответ на утверждение ${index + 1}`}
                >
                  <button
                    type="button"
                    role="radio"
                    aria-checked={selectedAnswer === 0}
                    disabled={isChecked}
                    onClick={() =>
                      handleAnswer(question.id, 0)
                    }
                    style={{
                      ...styles.answerButton,
                      ...(selectedAnswer === 0
                        ? styles.selectedButton
                        : {}),
                    }}
                  >
                    Мнение
                  </button>

                  <button
                    type="button"
                    role="radio"
                    aria-checked={selectedAnswer === 1}
                    disabled={isChecked}
                    onClick={() =>
                      handleAnswer(question.id, 1)
                    }
                    style={{
                      ...styles.answerButton,
                      ...(selectedAnswer === 1
                        ? styles.selectedButton
                        : {}),
                    }}
                  >
                    Факт
                  </button>
                </div>
              </article>
            );
          })}
        </div>

        {!isChecked ? (
          <footer style={styles.footer}>
            {!allQuestionsAnswered && (
              <p style={styles.hint}>
                Ответьте на все 12 утверждений, чтобы проверить
                результат.
              </p>
            )}

            <button
              type="button"
              disabled={!allQuestionsAnswered}
              onClick={handleCheck}
              style={{
                ...styles.primaryButton,
                ...(!allQuestionsAnswered
                  ? styles.disabledButton
                  : {}),
              }}
            >
              Проверить
            </button>
          </footer>
        ) : (
          <section style={styles.result}>
            <h2 style={styles.resultTitle}>
              Результат опроса
            </h2>

            {result.stupidityScore === 0 ? (
              <div style={styles.perfectResult}>
                <div style={styles.perfectEmoji} aria-hidden="true">
                  🎉
                </div>
                <p style={styles.perfectText}>
                  Поздравляю, в Вас я не вижу глупости!
                </p>
              </div>
            ) : (
              <div style={styles.stupidityResult}>
                <p style={styles.stupidityLabel}>
                  Ваша глупость
                </p>

                <div style={styles.stupidityNumber}>
                  {result.stupidityScore}
                  <span style={styles.stupidityMaximum}>
                    / {SCORED_QUESTIONS_COUNT}
                  </span>
                </div>

                <p style={styles.stupidityUnit}>
                  {result.stupidityScore}{" "}
                  {getDonQuixoteWord(result.stupidityScore)}
                </p>

                <div
                  style={styles.donQuixoteScale}
                  aria-label={`Уровень глупости: ${result.stupidityScore} из ${SCORED_QUESTIONS_COUNT}`}
                >
                  {Array.from(
                    { length: result.stupidityScore },
                    (_, index) => (
                      <DonQuixoteIcon
                        key={index}
                        width={48}
                        height={48}
                        style={styles.donQuixoteIcon}
                      />
                    ),
                  )}
                </div>
              </div>
            )}

            <p style={styles.resultText}>
              Правильно определено{" "}
              <strong>{result.correctOpinions}</strong>{" "}
              мнений и{" "}
              <strong>{result.correctFacts}</strong>{" "}
              фактов.
            </p>

            <p style={styles.resultNote}>
              Каждый неверный ответ добавляет одного Дон-Кихота.
            </p>

            <button
              type="button"
              onClick={handleRestart}
              style={styles.primaryButton}
            >
              Пройти новый опрос
            </button>
          </section>
        )}
      </section>
    </main>
  );
}

